def column_name(index):
    """Return the spreadsheet column name for a 1-based index."""
    if not isinstance(index, int) or isinstance(index, bool):
        raise ValueError("index must be an integer >= 1")
    if index < 1:
        raise ValueError("index must be >= 1")
    name = ""
    n = index
    while n > 0:
        n, rem = divmod(n - 1, 26)
        name = chr(ord("A") + rem) + name
    return name


def column_index(name):
    """Return the 1-based index of the given spreadsheet column name."""
    if not isinstance(name, str):
        raise ValueError("name must be a non-empty string of letters")
    if name == "":
        raise ValueError("name must not be empty")
    index = 0
    for ch in name:
        if "A" <= ch <= "Z":
            value = ord(ch) - ord("A") + 1
        elif "a" <= ch <= "z":
            value = ord(ch) - ord("a") + 1
        else:
            raise ValueError("name must contain only letters A-Z or a-z")
        index = index * 26 + value
    return index
